    public Map<String,Object> policy(AuthService.Session s,String role,PolicyInput input,UUID trace){return tenant(s,true,true,a->{
        if(!ROLES.contains(role)||input.canWrite()&&!input.canRead()||input.canShare()&&!input.canWrite()||role.equals("VIEWER")&&input.canWrite()||!input.canWrite()&&(input.creditAccess().equals("WRITE")||input.descriptionAccess().equals("WRITE")))throw ApiError.bad("权限组合无效：写入需允许读取，只读角色不能写入");
        var old=one("SELECT * FROM sys_role_policy WHERE tenant_id=:tenant AND role_code=:role",Map.of("tenant",a.tenant().id(),"role",role));
        boolean cr=input.contactCanRead()==null?(boolean)old.get("contact_can_read"):input.contactCanRead(),cw=input.contactCanWrite()==null?(boolean)old.get("contact_can_write"):input.contactCanWrite();
        boolean lr=input.leadCanRead()==null?(boolean)old.get("lead_can_read"):input.leadCanRead(),lw=input.leadCanWrite()==null?(boolean)old.get("lead_can_write"):input.leadCanWrite();
        boolean or=input.opportunityCanRead()==null?(boolean)old.get("opportunity_can_read"):input.opportunityCanRead(),ow=input.opportunityCanWrite()==null?(boolean)old.get("opportunity_can_write"):input.opportunityCanWrite();
        boolean tr=input.taskCanRead()==null?(boolean)old.get("task_can_read"):input.taskCanRead(),tw=input.taskCanWrite()==null?(boolean)old.get("task_can_write"):input.taskCanWrite();
        boolean ar=input.activityCanRead()==null?(boolean)old.get("activity_can_read"):input.activityCanRead(),aw=input.activityCanWrite()==null?(boolean)old.get("activity_can_write"):input.activityCanWrite();
        boolean rr=input.reportCanRead()==null?(boolean)old.get("report_can_read"):input.reportCanRead(),er=input.exportCanRead()==null?(boolean)old.get("export_can_read"):input.exportCanRead(),iw=input.importCanWrite()==null?(boolean)old.get("import_can_write"):input.importCanWrite();
        boolean fr=input.attachmentCanRead()==null?(boolean)old.get("attachment_can_read"):input.attachmentCanRead(),fw=input.attachmentCanWrite()==null?(boolean)old.get("attachment_can_write"):input.attachmentCanWrite();
        boolean pr=input.productCanRead()==null?(boolean)old.get("product_can_read"):input.productCanRead(),pw=input.productCanWrite()==null?(boolean)old.get("product_can_write"):input.productCanWrite(),qr=input.quoteCanRead()==null?(boolean)old.get("quote_can_read"):input.quoteCanRead(),qw=input.quoteCanWrite()==null?(boolean)old.get("quote_can_write"):input.quoteCanWrite(),pdf=input.quotePdfCanExport()==null?(boolean)old.get("quote_pdf_can_export"):input.quotePdfCanExport();
        boolean approve=input.quoteCanApprove()==null?(boolean)old.get("quote_can_approve"):input.quoteCanApprove();
        if(approve&&(!qr||!role.equals("SALES_MANAGER")))throw ApiError.bad("报价审批需销售经理角色及报价读取权限");
        if(pw&&!pr||qw&&!qr||pdf&&!qr||role.equals("VIEWER")&&(pw||qw||pdf))throw ApiError.bad("产品 / 报价写入及 PDF 导出权限组合无效");
        if(cw&&!cr||lw&&!lr||ow&&!or||tw&&!tr||aw&&!ar||fw&&!fr||role.equals("VIEWER")&&(cw||lw||ow||tw||aw||iw||fw))throw ApiError.bad("模块写入需允许读取，只读角色不能写入");
        boolean contractRead=input.contractCanRead()==null?(boolean)old.get("contract_can_read"):input.contractCanRead(),contractWrite=input.contractCanWrite()==null?(boolean)old.get("contract_can_write"):input.contractCanWrite(),contractAmend=input.contractCanAmend()==null?(boolean)old.get("contract_can_amend"):input.contractCanAmend(),receiptRead=input.receiptCanRead()==null?(boolean)old.get("receipt_can_read"):input.receiptCanRead(),receiptWrite=input.receiptCanWrite()==null?(boolean)old.get("receipt_can_write"):input.receiptCanWrite(),receiptConfirm=input.receiptCanConfirm()==null?(boolean)old.get("receipt_can_confirm"):input.receiptCanConfirm(),receiptReverse=input.receiptCanReverse()==null?(boolean)old.get("receipt_can_reverse"):input.receiptCanReverse(),tradeExport=input.tradeCanExport()==null?(boolean)old.get("trade_can_export"):input.tradeCanExport();
        if(contractWrite&&!contractRead||contractAmend&&(!contractWrite||!role.equals("SALES_MANAGER"))||receiptRead&&!contractRead||receiptWrite&&!receiptRead||(receiptConfirm||receiptReverse)&&(!receiptRead||!role.equals("SALES_MANAGER"))||tradeExport&&!contractRead||role.equals("VIEWER")&&(contractWrite||receiptWrite||tradeExport))throw ApiError.bad("合同 / 回款权限组合无效，确认与冲正仅允许销售经理");
        P3Access.policy(db,a.tenant().id(),role,old,input);P4Access.policy(db,a.tenant().id(),role,old,input);
        int changed=db.update("UPDATE sys_role_policy SET can_read=:read,can_write=:write,record_scope=:scope,credit_access=:credit,description_access=:description,can_share=:share,contact_can_read=:cr,contact_can_write=:cw,lead_can_read=:lr,lead_can_write=:lw,opportunity_can_read=:or,opportunity_can_write=:ow,task_can_read=:tr,task_can_write=:tw,activity_can_read=:ar,activity_can_write=:aw,report_can_read=:rr,export_can_read=:er,import_can_write=:iw,attachment_can_read=:fr,attachment_can_write=:fw,product_can_read=:pr,product_can_write=:pw,quote_can_read=:qr,quote_can_write=:qw,quote_pdf_can_export=:pdf,quote_can_approve=:approve,contract_can_read=:contractRead,contract_can_write=:contractWrite,contract_can_amend=:contractAmend,receipt_can_read=:receiptRead,receipt_can_write=:receiptWrite,receipt_can_confirm=:receiptConfirm,receipt_can_reverse=:receiptReverse,trade_can_export=:tradeExport,version=version+1 WHERE tenant_id=:tenant AND role_code=:role AND version=:version",map("read",input.canRead(),"write",input.canWrite(),"scope",input.recordScope(),"credit",input.creditAccess(),"description",input.descriptionAccess(),"share",input.canShare(),"cr",cr,"cw",cw,"lr",lr,"lw",lw,"or",or,"ow",ow,"tr",tr,"tw",tw,"ar",ar,"aw",aw,"rr",rr,"er",er,"iw",iw,"fr",fr,"fw",fw,"pr",pr,"pw",pw,"qr",qr,"qw",qw,"pdf",pdf,"approve",approve,"contractRead",contractRead,"contractWrite",contractWrite,"contractAmend",contractAmend,"receiptRead",receiptRead,"receiptWrite",receiptWrite,"receiptConfirm",receiptConfirm,"receiptReverse",receiptReverse,"tradeExport",tradeExport,"tenant",a.tenant().id(),"role",role,"version",input.expectedVersion()));
        if(changed!=1)throw ApiError.conflict("角色权限已变化，请刷新");audit(s,a.tenant().id(),"ROLE_POLICY_UPDATED",null,Map.of("role",role,"policy",input),trace);return view(one("SELECT * FROM sys_role_policy WHERE tenant_id=:tenant AND role_code=:role",Map.of("tenant",a.tenant().id(),"role",role)));
    });}

    public List<Map<String,Object>> renewals(AuthService.Session s,boolean platform){return platform?platform(s,()->rows("SELECT r.*,t.name AS tenant_name,p.name AS plan_name FROM sys_subscription_request r JOIN sys_tenant t ON t.id=r.tenant_id JOIN sys_plan p ON p.id=r.plan_id ORDER BY r.created_at DESC LIMIT 1000",Map.of())):tenant(s,true,false,a->rows("SELECT r.*,p.name AS plan_name FROM sys_subscription_request r JOIN sys_plan p ON p.id=r.plan_id WHERE r.tenant_id=:tenant ORDER BY r.created_at DESC",Map.of("tenant",a.tenant().id())));}
    public Map<String,Object> renewal(AuthService.Session s,RenewalInput input,String key,UUID trace){return tenant(s,true,false,a->{lockTenant(a.tenant().id());if(!Set.of(1,3,6,12).contains(input.months()))throw ApiError.bad("续费周期支持1、3、6或12个月");UUID id=once(a.tenant().id().toString(),s,"renewal.create",key,input,()->{var t=lockTenant(a.tenant().id());UUID created=UUID.randomUUID();long amount=Math.multiplyExact(number(t,"monthly_price_cents"),input.months());db.update("INSERT INTO sys_subscription_request(id,tenant_id,plan_id,applicant_member_id,months,amount_cents) VALUES(:id,:tenant,:plan,:member,:months,:amount)",Map.of("id",created,"tenant",a.tenant().id(),"plan",t.get("plan_id"),"member",a.tenant().memberId(),"months",input.months(),"amount",amount));audit(s,a.tenant().id(),"RENEWAL_REQUESTED",created,input,trace);return created;});return view(one("SELECT * FROM sys_subscription_request WHERE id=:id AND tenant_id=:tenant",Map.of("id",id,"tenant",a.tenant().id())));});}
    public static Instant renewedEnd(Instant expires,Instant now,int months,String timezone){return (expires.isAfter(now)?expires:now).atZone(ZoneId.of(timezone)).plusMonths(months).toInstant();}
    public Map<String,Object> decideRenewal(AuthService.Session s,UUID id,Decision input,UUID trace){return platform(s,()->{var initial=one("SELECT tenant_id FROM sys_subscription_request WHERE id=:id",Map.of("id",id));UUID tenant=(UUID)initial.get("tenant_id");var t=lockTenant(tenant);var r=one("SELECT * FROM sys_subscription_request WHERE id=:id FOR UPDATE",Map.of("id",id));if(!"PENDING".equals(r.get("status"))){if(input.status().equals(r.get("status")))return view(r);throw ApiError.conflict("申请已处理");}if(number(r,"version")!=input.expectedVersion())throw ApiError.conflict("申请已变化，请刷新");if(input.status().equals("CONFIRMED")&&!r.get("plan_id").equals(t.get("plan_id")))throw ApiError.conflict("企业套餐已变更，请重新提交续费申请");if(input.status().equals("CONFIRMED")&&text(input.paymentReference()).isEmpty())throw ApiError.bad("请填写人工核实收款的凭据编号");if(input.status().equals("REJECTED")&&text(input.reason()).isEmpty())throw ApiError.bad("请填写驳回原因");Instant from=null,end=null;if(input.status().equals("CONFIRMED")){Instant now=Instant.now(),old=instant(t,"subscription_end");from=old.isAfter(now)?old:now;end=renewedEnd(old,now,((Number)r.get("months")).intValue(),(String)t.get("timezone"));db.update("UPDATE sys_tenant SET subscription_end=:end,version=version+1 WHERE id=:id",Map.of("end",Timestamp.from(end),"id",tenant));}db.update("UPDATE sys_subscription_request SET status=:status,payment_reference=:payment,decision_reason=:reason,confirmed_by=:user,renewed_from=:from,renewed_until=:end,version=version+1,decided_at=now() WHERE id=:id",map("status",input.status(),"payment",text(input.paymentReference()),"reason",text(input.reason()),"user",s.userId(),"from",from==null?null:Timestamp.from(from),"end",end==null?null:Timestamp.from(end),"id",id));audit(s,tenant,"RENEWAL_"+input.status(),id,input,trace);return view(one("SELECT * FROM sys_subscription_request WHERE id=:id",Map.of("id",id)));});}
    public Map<String,Object> cancelRenewal(AuthService.Session s,UUID id,UUID trace){return tenant(s,true,false,a->{lockTenant(a.tenant().id());var r=one("SELECT * FROM sys_subscription_request WHERE tenant_id=:tenant AND id=:id FOR UPDATE",Map.of("tenant",a.tenant().id(),"id",id));if("CANCELLED".equals(r.get("status")))return view(r);if(!"PENDING".equals(r.get("status")))throw ApiError.conflict("申请已经处理");db.update("UPDATE sys_subscription_request SET status='CANCELLED',version=version+1,decided_at=now() WHERE id=:id",Map.of("id",id));audit(s,a.tenant().id(),"RENEWAL_CANCELLED",id,Map.of(),trace);return view(one("SELECT * FROM sys_subscription_request WHERE id=:id",Map.of("id",id)));});}

