    public Map<String,Object> grantSupport(AuthService.Session s,SupportInput input,String key,UUID trace){return tenant(s,true,true,a->{one("SELECT id FROM iam_user WHERE id=:id AND status='ACTIVE' AND is_platform_operator",Map.of("id",input.operatorUserId()));UUID id=once(a.tenant().id().toString(),s,"support.create",key,input,()->{UUID created=UUID.randomUUID();db.update("INSERT INTO sys_support_grant(id,tenant_id,operator_user_id,approver_member_id,reason,expires_at,allow_credit,allow_description) VALUES(:id,:tenant,:operator,:member,:reason,:end,:credit,:description)",Map.of("id",created,"tenant",a.tenant().id(),"operator",input.operatorUserId(),"member",a.tenant().memberId(),"reason",text(input.reason()),"end",Timestamp.from(Instant.now().plusSeconds(input.hours()*3600L)),"credit",input.allowCredit(),"description",input.allowDescription()));audit(s,a.tenant().id(),"SUPPORT_GRANTED",created,input,trace);return created;});return view(one("SELECT * FROM sys_support_grant WHERE tenant_id=:tenant AND id=:id",Map.of("tenant",a.tenant().id(),"id",id)));});}
    public void revokeSupport(AuthService.Session s,UUID id,UUID trace){tenant(s,true,false,a->{lockTenant(a.tenant().id());one("SELECT id FROM sys_support_grant WHERE tenant_id=:tenant AND id=:id",Map.of("tenant",a.tenant().id(),"id",id));db.update("UPDATE sys_support_grant SET revoked_at=coalesce(revoked_at,now()),version=version+1 WHERE tenant_id=:tenant AND id=:id AND revoked_at IS NULL",Map.of("tenant",a.tenant().id(),"id",id));audit(s,a.tenant().id(),"SUPPORT_REVOKED",id,Map.of(),trace);return null;});}
    public AuthService.Session enterSupport(AuthService.Session s,UUID id,UUID trace){return platform(s,()->{var g=one("SELECT g.* FROM sys_support_grant g JOIN sys_tenant t ON t.id=g.tenant_id WHERE g.id=:id AND g.operator_user_id=:user AND g.revoked_at IS NULL AND g.expires_at>now() AND t.status='ACTIVE'",Map.of("id",id,"user",s.userId()));UUID tenant=(UUID)g.get("tenant_id");db.update("UPDATE auth_session SET active_tenant_id=:tenant,support_grant_id=:grant WHERE id=:id",Map.of("tenant",tenant,"grant",id,"id",s.id()));audit(s,tenant,"SUPPORT_ENTERED",id,Map.of(),trace);return new AuthService.Session(s.id(),s.userId(),s.username(),s.displayName(),s.platformOperator(),s.csrf(),tenant,s.expiresAt(),s.mustChangePassword(),id);});}
